INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Iniciar animación \'Al hacer clic\' significa:', 'opcion_multiple', '["Automática", "Requiere clic del mouse", "Con teclado", "Con sonido"]', 'Requiere clic del mouse', 'La animación comienza al hacer clic.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Iniciar \'Con la anterior\' significa:', 'opcion_multiple', '["Requiere clic", "Inicia simultáneamente con animación anterior", "Inicia después", "No inicia"]', 'Inicia simultáneamente con animación anterior', 'Se ejecuta al mismo tiempo que la animación previa.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Iniciar \'Después de la anterior\' significa:', 'opcion_multiple', '["Requiere clic", "Inicia automáticamente después", "Inicia antes", "No inicia"]', 'Inicia automáticamente después', 'Comienza automáticamente al terminar la anterior.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Avanzar diapositiva \'Automáticamente después\' significa:', 'opcion_multiple', '["Requiere clic", "Cambia sola después de tiempo", "No cambia", "Imprime"]', 'Cambia sola después de tiempo', 'Cambia automáticamente tras el tiempo especificado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'diccionario[\'clave\'] accede a:', 'opcion_multiple', '["La clave", "El valor asociado", "Error", "Nada"]', 'El valor asociado', 'Devuelve el valor asociado a la clave.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función SI(A1>10,\"Aprobado\",\"Reprobado\") evalúa:', 'opcion_multiple', '["Una condición", "Un texto", "Una suma", "Un promedio"]', 'Una condición', 'SI evalúa una condición lógica y devuelve valores según sea VERDADERO o FALSO.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'CONTAR.SI(A1:A10,\">5\") cuenta:', 'opcion_multiple', '["Celdas mayores a 5", "Celdas iguales a 5", "Celdas menores a 5", "Total de celdas"]', 'Celdas mayores a 5', 'Cuenta celdas que cumplen el criterio especificado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'SUMAR.SI(A1:A10,\">10\",B1:B10) suma:', 'opcion_multiple', '["A1:A10", "B1:B10 donde A>10", "Todo el rango", "Solo A1:A10"]', 'B1:B10 donde A>10', 'Suma valores de B donde A cumple el criterio.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'El campo \'Valores\' en una tabla dinámica generalmente:', 'opcion_multiple', '["Contiene números a calcular", "Contiene texto", "Contiene fechas", "Está vacío"]', 'Contiene números a calcular', 'Área donde se colocan los datos numéricos a resumir.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'ELEGIR(2,\"A\",\"B\",\"C\") devuelve:', 'opcion_multiple', '["A", "B", "C", "Error"]', 'B', 'Selecciona el valor en la posición 2 del listado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'TEXTO(A1,\"dd/mm/aaaa\") convierte:', 'opcion_multiple', '["Número a texto", "Fecha a texto con formato", "Texto a número", "Nada"]', 'Fecha a texto con formato', 'Convierte un valor a texto con formato específico.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Range(\"A1\").Value = 10 asigna:', 'opcion_multiple', '["10 a A1", "A1 a 10", "Texto", "Fecha"]', '10 a A1', 'Asigna el valor 10 a la celda A1.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'MsgBox \"Hola\" muestra:', 'opcion_multiple', '["Una caja de mensaje", "Un error", "Una tabla", "Un gráfico"]', 'Una caja de mensaje', 'Muestra un cuadro de diálogo con el mensaje.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué atajo de teclado inicia la presentación desde la diapositiva actual?', 'opcion_multiple', '["F5", "Shift + F5", "Ctrl + F5", "Alt + F5"]', 'Shift + F5', 'Shift + F5 inicia la presentación desde la diapositiva en la que estás actualmente situado.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué tecla pone la pantalla en negro durante una presentación?', 'opcion_multiple', '["B o Punto", "W o Coma", "Esc", "Spacebar"]', 'B o Punto', 'La tecla B (Black) o el punto ocultan la presentación mostrando una pantalla negra.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué tecla pone la pantalla en blanco durante una presentación?', 'opcion_multiple', '["B", "W o Coma", "Esc", "Enter"]', 'W o Coma', 'La tecla W (White) o la coma ocultan la presentación mostrando una pantalla blanca.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué atajo de teclado activa el puntero de pluma durante la presentación?', 'opcion_multiple', '["Ctrl + P", "Ctrl + A", "Ctrl + L", "Ctrl + H"]', 'Ctrl + P', 'Ctrl + P cambia el cursor a un lápiz o pluma para realizar anotaciones en vivo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué atajo de teclado vuelve a activar el puntero de flecha estándar?', 'opcion_multiple', '["Ctrl + P", "Ctrl + A", "Ctrl + H", "Ctrl + E"]', 'Ctrl + A', 'Ctrl + A (Arrow) desactiva las herramientas de anotación y vuelve al puntero normal.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'En PowerPoint, para combinar varias formas en una sola conservando solo las áreas comunes, ¿qué herramienta se usa?', 'opcion_multiple', '["Unión", "Combinar", "Intersecar", "Fragmentar"]', 'Intersecar', 'Intersecar deja únicamente la parte que se traslapa entre todas las formas seleccionadas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué herramienta de combinación de formas recorta la forma del frente de la de atrás?', 'opcion_multiple', '["Unión", "Combinar", "Restar", "Fragmentar"]', 'Restar', 'La opción Restar elimina la forma superior y su intersección de la forma inferior.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué vista muestra el texto estructurado de las diapositivas sin imágenes ni formas?', 'opcion_multiple', '["Clasificador de diapositivas", "Vista de lectura", "Vista Esquema", "Patrón de diapositivas"]', 'Vista Esquema', 'La Vista Esquema organiza el contenido textual de manera jerárquica para edición rápida.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para reorganizar fácilmente diapositivas mediante miniaturas, la mejor vista es:', 'opcion_multiple', '["Vista Esquema", "Clasificador de diapositivas", "Vista de lectura", "Vista normal"]', 'Clasificador de diapositivas', 'El Clasificador de diapositivas muestra todas las diapositivas en miniatura para facilitar su ordenamiento.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué opción del Patrón de diapositivas asegura que el logo aparezca en toda la presentación?', 'opcion_multiple', '["Colocarlo en la diapositiva maestra superior del patrón", "Colocarlo en cada diseño secundario", "Pegarlo en la diapositiva 1", "Insertarlo como fondo de agua"]', 'Colocarlo en la diapositiva maestra superior del patrón', 'La primera diapositiva (maestra) del patrón replica sus elementos a todos los diseños subordinados.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué formato de exportación de PowerPoint genera una presentación interactiva autoejecutable sin abrir la interfaz de edición?', 'opcion_multiple', '[".pptx", ".ppsx", ".pdf", ".potx"]', '.ppsx', 'El formato .ppsx (PowerPoint Show) inicia directamente en pantalla completa al abrir el archivo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cuál es la función del ''Zoom de sección''?', 'opcion_multiple', '["Agrandar las letras de una diapositiva", "Crear un hipervínculo visual hacia una sección específica", "Mejorar la resolución de imágenes", "Exportar una parte de la diapositiva"]', 'Crear un hipervínculo visual hacia una sección específica', 'El Zoom de sección crea una vista en miniatura interactiva que lleva al usuario a esa sección al hacer clic.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para comprimir los archivos de video e imágenes dentro de una presentación, ¿dónde debemos ir?', 'opcion_multiple', '["Archivo > Información > Comprimir medios", "Insertar > Video > Comprimir", "Inicio > Organizar", "Diseño > Formato del fondo"]', 'Archivo > Información > Comprimir medios', 'Archivo > Información > Comprimir medios permite optimizar el tamaño de los videos de la presentación.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Si deseas guardar una presentación asegurando que fuentes no comunes se vean en otros equipos:', 'opcion_multiple', '["Debes exportar a .potx", "Debes activar ''Incrustar fuentes en el archivo'' en las opciones de guardar", "No se puede hacer", "Debes convertir la fuente a imagen"]', 'Debes activar ''Incrustar fuentes en el archivo'' en las opciones de guardar', 'Incrustar las fuentes en el archivo asegura que se carguen correctamente aunque el otro equipo no las tenga instaladas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cómo se activa la Vista Moderador al dar una presentación?', 'opcion_multiple', '["Tener dos pantallas y marcar ''Usar vista del moderador'' en la pestaña Presentación con diapositivas", "Presionar Ctrl + Alt + V", "Solo se activa en la pestaña Vista", "No requiere dos pantallas"]', 'Tener dos pantallas y marcar ''Usar vista del moderador'' en la pestaña Presentación con diapositivas', 'Requiere pantalla secundaria para que el expositor vea las notas del orador y el público solo la diapositiva.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué opción de configuración de audio hace que la música no se detenga al cambiar de diapositiva?', 'opcion_multiple', '["Ocultar durante la presentación", "Reproducir en todas las diapositivas", "Repetir la reproducción", "Reproducir en segundo plano"]', 'Reproducir en todas las diapositivas', '''Reproducir en todas las diapositivas'' mantiene el flujo del audio continuo a lo largo del cambio de diapositivas.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué permite hacer la característica ''Grabar presentación''?', 'opcion_multiple', '["Exportar solo el texto a Word", "Capturar audio, video de la cámara y gestos de lápiz del presentador diapositiva por diapositiva", "Solo capturar la pantalla", "Transmitir en vivo a YouTube"]', 'Capturar audio, video de la cámara y gestos de lápiz del presentador diapositiva por diapositiva', 'Permite grabar la narración y video sincronizados de manera nativa por diapositiva.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cuál es la función del panel ''Selección''?', 'opcion_multiple', '["Seleccionar plantillas", "Listar y renombrar los objetos de la diapositiva para gestionar su visibilidad y orden", "Elegir fuentes de texto", "Configurar transiciones"]', 'Listar y renombrar los objetos de la diapositiva para gestionar su visibilidad y orden', 'El Panel de Selección ayuda a ocultar o reordenar capas y elementos complejos dentro de una diapositiva.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué atajo de teclado duplica la diapositiva seleccionada?', 'opcion_multiple', '["Ctrl + C", "Ctrl + D", "Ctrl + Y", "Ctrl + N"]', 'Ctrl + D', 'Ctrl + D duplica rápidamente el elemento o diapositiva seleccionada en PowerPoint.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué atajo de teclado agrupa los objetos seleccionados?', 'opcion_multiple', '["Ctrl + G", "Ctrl + Shift + G", "Ctrl + A", "Ctrl + Alt + G"]', 'Ctrl + G', 'Ctrl + G agrupa los objetos seleccionados. Ctrl + Shift + G los desagrupa.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para cambiar la orientación de las diapositivas de Horizontal a Vertical:', 'opcion_multiple', '["Diseño > Tamaño de diapositiva > Personalizar", "Inicio > Orientación", "Archivo > Imprimir", "Vista > Clasificador de diapositivas"]', 'Diseño > Tamaño de diapositiva > Personalizar', 'Se cambia desde el Tamaño de diapositiva personalizado en la pestaña de Diseño.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué característica de SmartArt permite convertir una lista de viñetas de texto en un gráfico visual?', 'opcion_multiple', '["Convertir a SmartArt", "Diseños personalizados", "Insertar forma", "Cambiar colores"]', 'Convertir a SmartArt', 'La opción ''Convertir a SmartArt'' traduce listas jerárquicas de texto en diagramas vectoriales estructurados.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El efecto de transición que genera una transformación fluida animando objetos comunes entre diapositivas se llama:', 'opcion_multiple', '["Desvanecer", "Empuje", "Transformación (Morph)", "Barrido"]', 'Transformación (Morph)', 'Morph calcula la posición inicial y final de un objeto y realiza una interpolación suave.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué requiere la transición ''Transformación'' (Morph) para funcionar de manera óptima?', 'opcion_multiple', '["Tener dos diapositivas consecutivas con objetos idénticos o renombrados con ''!!''", "Un video incrustado", "Uso de macros", "Conexión a internet"]', 'Tener dos diapositivas consecutivas con objetos idénticos o renombrados con ''!!''', 'Morph rastrea elementos compartidos para interpolar su tamaño, posición y color entre dos diapositivas consecutivas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cómo se inserta un hipervínculo que vaya a una diapositiva específica de la misma presentación?', 'opcion_multiple', '["Insertar > Vínculo > Lugar de este documento", "Copiar y pegar la URL", "Archivo > Compartir", "Inicio > Hipervínculo externo"]', 'Insertar > Vínculo > Lugar de este documento', 'La opción ''Lugar de este documento'' muestra la jerarquía de diapositivas para elegir el destino.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Para qué sirve la opción ''Examinada en exposición (pantalla completa)'' en Configuración de la presentación?', 'opcion_multiple', '["Para dar control total al presentador", "Para modo Kiosco, donde la presentación corre en bucle y solo avanza con hipervínculos", "Para verla en web", "Para imprimirla"]', 'Para modo Kiosco, donde la presentación corre en bucle y solo avanza con hipervínculos', 'El modo Kiosco inhabilita el avance automático por clic para exposiciones en vitrinas comerciales.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué herramienta permite alinear exactamente un conjunto de objetos de forma horizontal o vertical?', 'opcion_multiple', '["Formato de forma > Organizar > Alinear", "Arrastrar a ojo", "Insertar tabla", "Patrón de diapositivas"]', 'Formato de forma > Organizar > Alinear', 'El menú Alinear distribuye objetos de forma exacta respecto a la diapositiva o entre sí.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cómo se desactiva una animación para que no se ejecute sin eliminarla del objeto?', 'opcion_multiple', '["Cambiar su inicio a ''Al hacer clic'' y no hacer clic", "Hacer clic en ''Ninguna'' en la galería de animaciones", "No se puede desactivar sin eliminar", "Ocultar la capa del objeto en el panel de selección"]', 'Hacer clic en ''Ninguna'' en la galería de animaciones', 'Seleccionar ''Ninguna'' remueve el desencadenador del objeto sin quitar el objeto en sí.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El ''Desencadenador'' en animaciones sirve para:', 'opcion_multiple', '["Cerrar la presentación", "Iniciar la animación al hacer clic en un elemento específico de la diapositiva", "Reproducir música", "Avanzar de forma aleatoria"]', 'Iniciar la animación al hacer clic en un elemento específico de la diapositiva', 'Los desencadenadores inician animaciones basándose en clics sobre elementos específicos (botones o formas).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Si insertamos un icono SVG en PowerPoint, ¿cómo podemos cambiar el color de sus partes de manera independiente?', 'opcion_multiple', '["No se puede modificar", "Clic derecho > Convertir a forma", "Exportar como imagen", "Editar en Excel"]', 'Clic derecho > Convertir a forma', 'Convertir a forma transforma el archivo SVG en formas nativas editables del Office.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué tipo de animación altera las propiedades de tamaño, color o rotación de un objeto sin que este entre o salga de escena?', 'opcion_multiple', '["Animación de Entrada", "Animación de Énfasis", "Animación de Salida", "Ruta de animación"]', 'Animación de Énfasis', 'Las animaciones de énfasis destacan un elemento variando su rotación, tamaño u opacidad.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cómo se crea una presentación personalizada en PowerPoint?', 'opcion_multiple', '["Archivo > Guardar como nuevo", "Presentación con diapositivas > Presentación personalizada", "Insertar > Nueva presentación", "Inicio > Copiar presentación"]', 'Presentación con diapositivas > Presentación personalizada', 'Permite agrupar y nombrar un subconjunto de diapositivas para presentarlas sin alterar el archivo original.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'La regla, las líneas de cuadrícula y las guías de PowerPoint se configuran en la pestaña:', 'opcion_multiple', '["Inicio", "Diseño", "Vista", "Presentación con diapositivas"]', 'Vista', 'Pestaña Vista contiene la sección de Mostrar con opciones de Regla, Guías y Cuadrícula.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué es un ''Patrón de documentos'' en PowerPoint?', 'opcion_multiple', '["El diseño de impresión para las hojas que se entregan a la audiencia", "La plantilla del tema", "La portada", "Un reporte externo"]', 'El diseño de impresión para las hojas que se entregan a la audiencia', 'Define el formato, cabeceras y pie de página de los documentos impresos entregados a los asistentes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué hace el botón ''Copiar animación''?', 'opcion_multiple', '["Duplica el objeto", "Copia los efectos de animación de un objeto y los aplica a otro", "Crea una diapositiva", "Guarda el archivo"]', 'Copia los efectos de animación de un objeto y los aplica a otro', 'Copia toda la secuencia y tiempos de animación de un elemento a otro con un solo clic.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cuál es el límite máximo predeterminado de diapositivas que puede tener una presentación?', 'opcion_multiple', '["100", "500", "No tiene un límite fijo (depende de la memoria)", "1000"]', 'No tiene un límite fijo (depende de la memoria)', 'No hay un límite definido en software, el límite real es la memoria y rendimiento del equipo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Al exportar una presentación como PDF, las notas del orador:', 'opcion_multiple', '["Se incluyen automáticamente en la parte inferior de cada página", "No se exportan a menos que configures ''Páginas de notas'' en las opciones de publicación", "Siempre se eliminan", "Se colocan como comentarios flotantes"]', 'No se exportan a menos que configures ''Páginas de notas'' en las opciones de publicación', 'Debes configurar la opción ''Páginas de notas'' al publicar o imprimir para ver el texto complementario del orador.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El ''Intervalo de diapositivas'' en transiciones determina:', 'opcion_multiple', '["La duración de la presentación", "El tiempo que la diapositiva permanece en pantalla antes del avance automático", "La velocidad de la música", "El tamaño de la pantalla"]', 'El tiempo que la diapositiva permanece en pantalla antes del avance automático', 'Controla el avance de tiempo en modo automático para presentaciones autoejecutables.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué función cumple el panel ''Ideas de diseño'' (Designer)?', 'opcion_multiple', '["Corregir ortografía", "Sugerir diseños visuales automatizados basados en el contenido de la diapositiva", "Buscar imágenes en la web", "Configurar fuentes"]', 'Sugerir diseños visuales automatizados basados en el contenido de la diapositiva', 'Usa inteligencia en la nube para armar composiciones fotográficas y de texto con un solo clic.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué tipo de archivo es una plantilla de PowerPoint?', 'opcion_multiple', '[".pptx", ".potx", ".ppsx", ".pdf"]', '.potx', 'El formato .potx es el formato oficial para guardar plantillas de diseño reutilizables.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cuál es la proporción de pantalla panorámica moderna por defecto en PowerPoint?', 'opcion_multiple', '["4:3", "16:9", "16:10", "1:1"]', '16:9', 'El formato 16:9 (Alta Definición) es el estándar panorámico para pantallas y proyectores actuales.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué ocurre si eliminas una diapositiva del Patrón de diapositivas?', 'opcion_multiple', '["Se borra la presentación completa", "Cualquier diapositiva que use ese diseño específico perderá su formato o volverá al diseño base", "No se puede eliminar", "Se duplica"]', 'Cualquier diapositiva que use ese diseño específico perderá su formato o volverá al diseño base', 'El patrón controla los layouts disponibles. Si quitas uno, las hojas asociadas se reajustan al diseño maestro.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para insertar un video de YouTube en una presentación:', 'opcion_multiple', '["Debes descargarlo primero obligatoriamente", "Insertar > Video > Videos en línea e introducir la URL del video", "Copiar la miniatura", "No se permite en PowerPoint"]', 'Insertar > Video > Videos en línea e introducir la URL del video', 'La opción ''Videos en línea'' permite enlazar y reproducir contenido de YouTube, Vimeo o Stream directamente con internet.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para ocultar una diapositiva sin borrarla de la presentación:', 'opcion_multiple', '["Moverla al patrón", "Clic derecho sobre la miniatura > Ocultar diapositiva", "Ocultar en panel de selección", "Arrastrarla al final"]', 'Clic derecho sobre la miniatura > Ocultar diapositiva', 'Ocultar diapositiva hace que no se muestre durante la reproducción pero permanezca editable en el archivo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El ''Patrón de notas'' permite configurar:', 'opcion_multiple', '["El tamaño de las diapositivas", "La distribución del texto de notas y la miniatura de diapositiva al imprimir páginas de notas", "La velocidad del expositor", "Los comentarios"]', 'La distribución del texto de notas y la miniatura de diapositiva al imprimir páginas de notas', 'Define el diseño e información de la hoja impresa que contiene la diapositiva y las anotaciones del orador.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué herramienta permite recortar una imagen con una forma geométrica específica en PowerPoint?', 'opcion_multiple', '["Formato de imagen > Recortar > Recortar a la forma", "Combinar formas", "Efectos artísticos", "Quitar fondo"]', 'Formato de imagen > Recortar > Recortar a la forma', 'La función ''Recortar a la forma'' ajusta el contorno de la imagen al de la figura geométrica seleccionada.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué hace la herramienta ''Quitar fondo'' en PowerPoint?', 'opcion_multiple', '["Elimina toda la diapositiva", "Intenta separar el sujeto principal de la imagen de su fondo de forma automática", "Pone el fondo negro", "Modifica el tema"]', 'Intenta separar el sujeto principal de la imagen de su fondo de forma automática', 'Es un extractor de siluetas integrado para imágenes con fondos sólidos o contrastados.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cuál es la función del ''Cuentagotas'' en las herramientas de formato?', 'opcion_multiple', '["Medir la pantalla", "Capturar y aplicar cualquier color exacto de la pantalla al elemento seleccionado", "Limpiar el diseño", "Cambiar fuentes"]', 'Capturar y aplicar cualquier color exacto de la pantalla al elemento seleccionado', 'Permite clonar colores de fotos u otros elementos para mantener coherencia cromática.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Si deseas agrupar un elemento de texto y una forma, pero la opción ''Agrupar'' está deshabilitada, ¿cuál es la razón común?', 'opcion_multiple', '["El texto es demasiado largo", "Uno de los objetos seleccionados es un marcador de posición del patrón", "Están en diferentes diapositivas", "Están bloqueados por contraseña"]', 'Uno de los objetos seleccionados es un marcador de posición del patrón', 'Los marcadores de posición estructurales del patrón no pueden agruparse con formas libres de la diapositiva.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué formato de exportación de PowerPoint genera un video de alta calidad de la presentación completa?', 'opcion_multiple', '[".mp4", ".gif", ".avi", ".mov"]', '.mp4', 'PowerPoint exporta de forma nativa a video MP4 incluyendo transiciones y narraciones grabadas.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El ''Patrón de diapositivas'' maneja jerarquías. ¿Cuántos patrones de diapositivas principales puede tener una sola presentación?', 'opcion_multiple', '["Solo 1", "Máximo 5", "Múltiples (puedes insertar más de un patrón en la misma presentación)", "Depende del tema"]', 'Múltiples (puedes insertar más de un patrón en la misma presentación)', 'Una presentación puede contener múltiples patrones principales si se combinan temas o plantillas diferentes.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué son los ''Comentarios'' en PowerPoint?', 'opcion_multiple', '["Notas de orador", "Mensajes flotantes de revisión que no aparecen en la presentación en pantalla completa", "El título del tema", "Hipervínculos web"]', 'Mensajes flotantes de revisión que no aparecen en la presentación en pantalla completa', 'Herramienta colaborativa de notas al margen para revisión y edición conjunta.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para cambiar la tipografía completa de una presentación de forma automática sin editar diapositiva por diapositiva:', 'opcion_multiple', '["Usar Reemplazar Fuentes en Inicio > Edición", "Patrón de diapositivas > Fuentes", "Ambas opciones son correctas", "No se puede hacer"]', 'Ambas opciones son correctas', 'Ambos métodos automatizan el cambio tipográfico en cascada para todo el archivo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'La vista de lectura sirve principalmente para:', 'opcion_multiple', '["Editar texto", "Visualizar la presentación en una ventana normal con controles sencillos sin usar pantalla completa", "Ver el patrón", "Imprimir"]', 'Visualizar la presentación en una ventana normal con controles sencillos sin usar pantalla completa', 'Ideal para revisar la presentación en laptops sin perder la visibilidad de otras ventanas abiertas.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Un modelo 3D insertado en PowerPoint puede:', 'opcion_multiple', '["Solo verse como imagen plana", "Rotarse en los 360 grados y animarse con efectos tridimensionales nativos", "Solo usarse con macros", "Convertirse a tabla"]', 'Rotarse en los 360 grados y animarse con efectos tridimensionales nativos', 'PowerPoint soporta elementos 3D (.glb) interactivos con rotaciones y transiciones dedicadas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cuál es la función del ''Área de notas''?', 'opcion_multiple', '["Escribir recordatorios para el público", "Escribir apuntes del presentador visibles solo en Vista Moderador o impresos", "Guardar imágenes", "No tiene utilidad"]', 'Escribir apuntes del presentador visibles solo en Vista Moderador o impresos', 'Anotaciones privadas del expositor para guiar su discurso sin saturar la diapositiva.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para reproducir un sonido de fondo de forma continua a lo largo de toda la presentación:', 'opcion_multiple', '["Insertar en diapositiva 1 > Reproducir en todas las diapositivas + Repetir reproducción", "Pegar el audio en cada hoja", "Usar macros de audio", "Configurar en transiciones"]', 'Insertar en diapositiva 1 > Reproducir en todas las diapositivas + Repetir reproducción', 'La combinación de ambas opciones mantiene la reproducción del clip musical en bucle continuo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Al guardar como plantilla (.potx), el archivo por defecto se almacena en:', 'opcion_multiple', '["El Escritorio", "La carpeta de plantillas personalizadas de Office", "Descargas", "Cualquier lugar"]', 'La carpeta de plantillas personalizadas de Office', 'Office gestiona una ruta centralizada para que tus plantillas aparezcan en la pestaña ''Personal'' al crear nuevos archivos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué es la ''Gama de colores'' en PowerPoint?', 'opcion_multiple', '["Los colores del tema", "La paleta de 4 colores armónicos predefinidos en las variantes del diseño", "El brillo de pantalla", "La resolución de impresión"]', 'La paleta de 4 colores armónicos predefinidos en las variantes del diseño', 'Es la paleta coordinada que define el color de fuentes, formas y gráficos para mantener coherencia visual.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El ''Intervalo de tiempo'' de una animación indica:', 'opcion_multiple', '["Cuándo finaliza la presentación", "El tiempo en segundos que dura la ejecución del efecto visual", "El retraso de diapositiva", "La velocidad de transición"]', 'El tiempo en segundos que dura la ejecución del efecto visual', 'Controla qué tan rápido o lento ocurre el efecto visual de la animación.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué vista nos permite ver cómo se vería la presentación impresa en escala de grises?', 'opcion_multiple', '["Vista de lectura", "Vista > Escala de grises", "Clasificador de diapositivas", "Patrón de documentos"]', 'Vista > Escala de grises', 'Ayuda a auditar si el contraste de los colores es adecuado para impresiones económicas en blanco y negro.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cómo se bloquean las diapositivas para que otros no modifiquen el diseño estructural de la presentación?', 'opcion_multiple', '["Archivo > Información > Proteger presentación > Cifrar con contraseña o Marcar como final", "No se puede proteger", "Eliminar el patrón", "Exportar a imagen"]', 'Archivo > Información > Proteger presentación > Cifrar con contraseña o Marcar como final', 'Se puede restringir la edición mediante contraseña o indicar que el documento es de solo lectura (Final).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para cambiar las dimensiones exactas de una presentación en centímetros para impresión comercial:', 'opcion_multiple', '["Diseño > Tamaño de diapositiva > Personalizar tamaño de diapositiva", "Archivo > Imprimir > Ajustar", "Inicio > Configurar", "Vista > Escala de grises"]', 'Diseño > Tamaño de diapositiva > Personalizar tamaño de diapositiva', 'El menú de personalización de tamaño permite introducir medidas personalizadas de ancho y alto en centímetros.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Qué comando abre el cuadro de diálogo de ortografía en PowerPoint?', 'opcion_multiple', '["F1", "F7", "Alt + F7", "F5"]', 'F7', 'La tecla F7 inicia el corrector ortográfico y gramatical en todo el documento de PowerPoint.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, '¿Cuál es la función del comando ''Restablecer'' en la pestaña Inicio?', 'opcion_multiple', '["Borrar todo el contenido de la diapositiva", "Restablecer la posición, tamaño y formato de los marcadores de posición según la plantilla del patrón", "Cerrar el archivo sin guardar", "Reiniciar la numeración"]', 'Restablecer la posición, tamaño y formato de los marcadores de posición según la plantilla del patrón', 'Regresa los elementos alterados manualmente a su formato y distribución estándar definida en el patrón.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Al insertar un gráfico de barras, ¿qué herramienta auxiliar se abre para ingresar los datos?', 'opcion_multiple', '["Una pequeña hoja de datos de Excel integrada", "Un cuadro de texto libre", "El editor de Word", "Access"]', 'Una pequeña hoja de datos de Excel integrada', 'PowerPoint utiliza una ventana reducida del motor de Excel para gestionar los datos tabulares del gráfico.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo de resolución de conflictos de Thomas-Kilmann, el estilo ''Complaciente'' se caracteriza por:', 'opcion_multiple', '["Alta asertividad y baja cooperación", "Baja asertividad y alta cooperación", "Baja asertividad y baja cooperación", "Alta asertividad y alta cooperación"]', 'Baja asertividad y alta cooperación', 'El complaciente cede ante las demandas del otro, priorizando la relación sobre el interés propio.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El estilo ''Evasivo'' en Thomas-Kilmann implica:', 'opcion_multiple', '["Enfrentar el problema de inmediato", "Baja asertividad y baja cooperación (ignorar o posponer el conflicto)", "Buscar un acuerdo intermedio", "Imponer sus condiciones"]', 'Baja asertividad y baja cooperación (ignorar o posponer el conflicto)', 'El evasor no persigue ni sus intereses ni los del otro, posponiendo o retirándose del conflicto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El estilo ''Colaborativo'' busca:', 'opcion_multiple', '["Que ambas partes cedan un poco", "Una solución integradora que satisfaga plenamente a ambos (Ganar-Ganar)", "Que uno gane todo", "Evitar discutir"]', 'Una solución integradora que satisfaga plenamente a ambos (Ganar-Ganar)', 'La colaboración requiere explorar alternativas creativas para cubrir todos los intereses subyacentes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En negociación, la sigla MAPAN (o BATNA en inglés) significa:', 'opcion_multiple', '["Mejor Alternativa Posible a un Acuerdo Negociado", "Matriz de Planificación Analítica y Negociación", "Modelo de Acción Prioritaria Ante Conflictos", "Mecanismo Avanzado de Puntos y Acuerdos"]', 'Mejor Alternativa Posible a un Acuerdo Negociado', 'Es tu mejor opción de reserva si la negociación actual fracasa y no se logra firmar un acuerdo.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El primer principio del Modelo de Negociación de Harvard es:', 'opcion_multiple', '["Enfocarse en las posiciones de las partes", "Separar a las personas del problema", "Negociar bajo presión de tiempo", "Exigir concesiones inmediatas"]', 'Separar a las personas del problema', 'Ayuda a tratar con empatía a los negociadores mientras se es firme con los objetivos del acuerdo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo de negociación de Harvard, ¿cuál es la diferencia entre ''Posiciones'' e ''Intereses''?', 'opcion_multiple', '["No hay diferencia", "Las posiciones son lo que pides; los intereses son el porqué lo pides", "Los intereses son demandas económicas y posiciones son posturas éticas", "Las posiciones son fijas y los intereses cambian"]', 'Las posiciones son lo que pides; los intereses son el porqué lo pides', 'Identificar los intereses reales permite encontrar soluciones creativas que las posiciones rígidas bloquean.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El Modelo de Desarrollo de Equipos de Tuckman define las siguientes fases en orden:', 'opcion_multiple', '["Formación, Conflicto, Normalización, Desempeño, Disolución", "Inicio, Planificación, Ejecución, Control, Cierre", "Formación, Desempeño, Cierre", "Conflicto, Formación, Normalización, Cierre"]', 'Formación, Conflicto, Normalización, Desempeño, Disolución', 'Secuencia clásica del comportamiento de equipos humanos en proyectos de largo plazo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La fase de ''Normalización'' (Norming) en el modelo de Tuckman se caracteriza por:', 'opcion_multiple', '["Luchas de poder y desacuerdos constantes", "Establecimiento de reglas de juego, roles claros y cohesión grupal", "Alto rendimiento sin supervisión", "El fin del equipo"]', 'Establecimiento de reglas de juego, roles claros y cohesión grupal', 'Es la etapa donde el equipo empieza a trabajar de forma armoniosa y acepta las directrices del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Las ''5 Cs del Trabajo en Equipo'' son:', 'opcion_multiple', '["Comunicación, Coordinación, Complementariedad, Confianza, Compromiso", "Calidad, Costo, Control, Cambios, Cierre", "Capacidad, Criterio, Colaboración, Control, Cohesión", "Cercanía, Comunicación, Constancia, Coherencia, Compromiso"]', 'Comunicación, Coordinación, Complementariedad, Confianza, Compromiso', 'Es el marco de referencia que potencia la sinergia y efectividad de un grupo de colaboradores.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Qué describe el concepto de ''Complementariedad'' en un equipo?', 'opcion_multiple', '["Que todos tengan la misma formación", "Que cada miembro domine una parcela del proyecto aportando destrezas distintas", "Que compartan el mismo horario", "Que piensen igual"]', 'Que cada miembro domine una parcela del proyecto aportando destrezas distintas', 'La complementariedad permite sumar habilidades especializadas para resolver problemas complejos de forma integral.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El estilo de Liderazgo ''Laissez-faire'' se define como:', 'opcion_multiple', '["Liderazgo enfocado en castigos", "Dar total libertad al equipo en la toma de decisiones sin intervenir activamente (dejar hacer)", "Liderazgo democrático extremo", "Liderazgo dictatorial"]', 'Dar total libertad al equipo en la toma de decisiones sin intervenir activamente (dejar hacer)', 'El líder laissez-faire actúa como facilitador pasivo, confiando en la alta madurez del equipo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El Liderazgo Transformacional se enfoca en:', 'opcion_multiple', '["Intercambios transaccionales (premios y castigos)", "Inspirar y motivar a los seguidores a innovar y crear cambios positivos en la organización", "Mantener las rutinas sin cambios", "Tomar decisiones de forma aislada"]', 'Inspirar y motivar a los seguidores a innovar y crear cambios positivos en la organización', 'Busca el crecimiento personal de los colaboradores y una visión compartida de futuro.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Según Daniel Goleman, la ''Autorregulación'' es:', 'opcion_multiple', '["Conocer tus fortalezas", "La capacidad de controlar o redirigir impulsos y estados de ánimo perturbadores", "Motivarse a uno mismo", "Entender a los demás"]', 'La capacidad de controlar o redirigir impulsos y estados de ánimo perturbadores', 'Es el pilar de la inteligencia emocional que evita reacciones impulsivas ante situaciones estresantes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En inteligencia emocional, ¿qué diferencia a la Empatía Cognitiva de la Empatía Emocional?', 'opcion_multiple', '["No tienen relación", "La cognitiva es entender el pensamiento del otro; la emocional es sentir su emoción física o mentalmente", "La emocional es debilidad y la cognitiva es fortaleza", "La cognitiva es innata y la emocional se aprende"]', 'La cognitiva es entender el pensamiento del otro; la emocional es sentir su emoción física o mentalmente', 'La cognitiva permite comprender perspectivas ajenas racionalmente, mientras que la emocional conecta con el sentir afectivo.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La Matriz de Eisenhower clasifica las tareas en base a dos dimensiones:', 'opcion_multiple', '["Tiempo y Dinero", "Importancia y Urgencia", "Esfuerzo y Recompensa", "Dificultad y Plazo"]', 'Importancia y Urgencia', 'Divide las actividades en cuatro cuadrantes para priorizar qué hacer, delegar, agendar o eliminar.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Según la Matriz de Eisenhower, una tarea ''Importante pero No Urgente'' debe ser:', 'opcion_multiple', '["Hacerse de inmediato", "Planificarse (agendar cuándo hacerla)", "Delegarse a otro", "Eliminarse"]', 'Planificarse (agendar cuándo hacerla)', 'Las tareas importantes no urgentes son clave para el desarrollo estratégico a largo plazo y deben calendarizarse.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La Ley de Parkinson sobre la gestión del tiempo establece que:', 'opcion_multiple', '["El trabajo se expande hasta llenar el tiempo disponible para su realización", "El 80% de los resultados viene del 20% del esfuerzo", "El tiempo es dinero", "La prisa genera errores"]', 'El trabajo se expande hasta llenar el tiempo disponible para su realización', 'Si asignas un mes a una tarea que requiere dos días, inconscientemente tardarás el mes completo en finalizarla.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La Técnica Pomodoro propone estructurar el trabajo en intervalos de:', 'opcion_multiple', '["50 minutos de trabajo y 10 de descanso", "25 minutos de concentración y 5 de descanso", "2 horas de trabajo sin descanso", "10 minutos de trabajo y 5 de descanso"]', '25 minutos de concentración y 5 de descanso', 'Intervalos cortos de alta concentración (pomodoros) evitan la fatiga mental y aumentan el foco.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En comunicación asertiva, la ''Técnica del Sándwich'' para dar feedback consiste en:', 'opcion_multiple', '["Invitar a comer al colaborador", "Estructurar el mensaje con: 1) Comentario positivo, 2) Área de mejora, 3) Comentario positivo/motivador", "Dar la retroalimentación de forma dura y rápida", "Ignorar los errores y centrarse en lo positivo"]', 'Estructurar el mensaje con: 1) Comentario positivo, 2) Área de mejora, 3) Comentario positivo/motivador', 'Envuelve la crítica constructiva entre elogios sinceros para reducir la postura defensiva del receptor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El término ''Resiliencia'' en el ámbito personal se define como:', 'opcion_multiple', '["Evitar situaciones difíciles", "La capacidad de adaptarse y sobreponerse con éxito a la adversidad, trauma o estrés", "Ignorar las críticas de otros", "Mantenerse rígido en sus convicciones"]', 'La capacidad de adaptarse y sobreponerse con éxito a la adversidad, trauma o estrés', 'Capacidad humana de salir fortalecido tras experimentar crisis o fracasos en la vida personal o profesional.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Qué caracteriza a un estilo de comunicación ''Pasivo-Agresivo''?', 'opcion_multiple', '["Expresar sus opiniones de manera abierta e hiriente", "Evitar el enfrentamiento directo pero manifestar enojo de forma indirecta o encubierta", "No opinar sobre nada", "Comunicación asertiva de alto nivel"]', 'Evitar el enfrentamiento directo pero manifestar enojo de forma indirecta o encubierta', 'Usa sarcasmo, inacción voluntaria u hostilidad sutil en lugar de manifestar su desacuerdo formalmente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Qué es la ''Escucha Activa''?', 'opcion_multiple', '["Oír al interlocutor mientras haces otra actividad", "Escuchar con atención consciente, procesando el mensaje completo y demostrando comprensión verbal y no verbal", "Interrumpir constantemente para dar tu opinión", "Aceptar todo lo que dice la otra persona sin cuestionar"]', 'Escuchar con atención consciente, procesando el mensaje completo y demostrando comprensión verbal y no verbal', 'Implica concentración, empatía y feedback (como parafrasear) para asegurar que el canal de comunicación sea correcto.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En comunicación no verbal, el estudio de los gestos, expresiones faciales y movimientos corporales se llama:', 'opcion_multiple', '["Proxémica", "Kinesia (o Quinésica)", "Paralenguaje", "Cronémica"]', 'Kinesia (o Quinésica)', 'La kinesia analiza la expresión corporal y los ademanes como transmisores de emociones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La ''Proxémica'' es la disciplina que estudia:', 'opcion_multiple', '["El tono de voz", "El uso del espacio físico y la distancia entre personas durante la interacción", "La velocidad del habla", "El contacto visual"]', 'El uso del espacio físico y la distancia entre personas durante la interacción', 'Analiza las distancias (íntima, personal, social y pública) y cómo influyen en las dinámicas relacionales.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El ''Paralenguaje'' incluye elementos como:', 'opcion_multiple', '["Las palabras exactas seleccionadas", "El tono, volumen, ritmo y pausas de la voz", "La postura de los hombros", "La distancia física"]', 'El tono, volumen, ritmo y pausas de la voz', 'Son los aspectos acústicos no verbales de la comunicación verbal que matizan el mensaje.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El sesgo cognitivo conocido como ''Efecto Halo'' consiste en:', 'opcion_multiple', '["Analizar racionalmente a una persona", "Juzgar el carácter completo de una persona basándose en una sola característica visible (ej. apariencia)", "Trabajar mejor bajo presión", "Olvidar los errores cometidos"]', 'Juzgar el carácter completo de una persona basándose en una sola característica visible (ej. apariencia)', 'Provoca impresiones erróneas generalizadas a partir de rasgos iniciales percibidos de forma subjetiva.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Cuál es la principal ventaja de la ''Sinérgía'' en el trabajo colaborativo?', 'opcion_multiple', '["Que se trabaja menos tiempo", "Que el resultado del esfuerzo conjunto es superior a la suma de los aportes individuales (1 + 1 = 3)", "Que no hay diferencias de opinión", "Que el líder toma todas las decisiones"]', 'Que el resultado del esfuerzo conjunto es superior a la suma de los aportes individuales (1 + 1 = 3)', 'Es la integración armoniosa de talentos individuales que maximiza la capacidad operativa de un grupo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El término ''Pensamiento Crítico'' implica:', 'opcion_multiple', '["Criticar destructivamente el trabajo de los demás", "Analizar, evaluar y cuestionar información de forma objetiva y lógica para tomar decisiones racionales", "Seguir las instrucciones del líder al pie de la letra", "Aceptar opiniones comunes sin indagar"]', 'Analizar, evaluar y cuestionar información de forma objetiva y lógica para tomar decisiones racionales', 'Busca fundamentar verdades basándose en evidencia sólida en lugar de suposiciones o emociones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo situacional de liderazgo, si tu equipo tiene ''Baja competencia y Alta motivación'', el estilo recomendado es:', 'opcion_multiple', '["Delegar", "Dirigir / Instruir (Dar instrucciones claras e inspeccionar de cerca)", "Apoyar", "Laissez-faire"]', 'Dirigir / Instruir (Dar instrucciones claras e inspeccionar de cerca)', 'El equipo requiere guía técnica inmediata ya que tiene la actitud pero carece del conocimiento del proceso.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Si el equipo posee ''Alta competencia y Alta motivación'', el rol óptimo del líder es:', 'opcion_multiple', '["Dirigir", "Delegar (Otorgar autonomía y control del trabajo)", "Persuadir", "Controlar al detalle"]', 'Delegar (Otorgar autonomía y control del trabajo)', 'En niveles de madurez técnica altos, el micro-management desmotiva; se debe delegar responsabilidad con confianza.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La ''Escucha Empática'' difiere de la escucha activa en que:', 'opcion_multiple', '["Es más rápida", "Se enfoca en comprender los sentimientos, necesidades y la perspectiva interna del otro, sin juzgar", "Presta atención solo al contenido técnico", "Busca debatir los argumentos"]', 'Se enfoca en comprender los sentimientos, necesidades y la perspectiva interna del otro, sin juzgar', 'Su propósito es conectar con el estado emocional del interlocutor antes de formular soluciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Un síntoma característico del estrés laboral crónico o ''Burnout'' es:', 'opcion_multiple', '["Aumento de la energía", "Agotamiento físico y mental extremo, cinismo hacia el trabajo y baja eficacia percibida", "Deseo de asumir nuevos retos", "Gran optimismo en el equipo"]', 'Agotamiento físico y mental extremo, cinismo hacia el trabajo y baja eficacia percibida', 'Reconocido por la OMS como desgaste ocupacional severo que afecta la salud del colaborador.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Para gestionar eficazmente las críticas destructivas en el trabajo, la mejor postura es:', 'opcion_multiple', '["Responder con agresión para defenderse", "Escuchar con calma, separar la carga emocional del mensaje e identificar si hay datos útiles para el aprendizaje", "Ignorar por completo a la persona", "Aceptarlo con resignación y deprimirse"]', 'Escuchar con calma, separar la carga emocional del mensaje e identificar si hay datos útiles para el aprendizaje', 'La asertividad y autorregulación emocional transforman la hostilidad ajena en una oportunidad de autoanálisis.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Qué promueve la ''Seguridad Psicológica'' en un equipo de trabajo?', 'opcion_multiple', '["Tener guardias de seguridad en la oficina", "La creencia de que nadie será castigado o humillado por cometer un error, proponer ideas o hacer preguntas", "Trabajar en cubículos separados", "Evitar hablar de temas personales"]', 'La creencia de que nadie será castigado o humillado por cometer un error, proponer ideas o hacer preguntas', 'Es la base de la innovación y la alta productividad en equipos de alto rendimiento (como el Proyecto Aristóteles de Google).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Un obstáculo común para el trabajo en equipo es el ''Efecto Ringelmann'' (o Holgazanería Social), que consiste en:', 'opcion_multiple', '["Que los miembros compiten por el liderazgo", "La tendencia de los individuos a esforzarse menos cuando trabajan en grupo que cuando lo hacen solos", "Que el equipo se divide por género", "Que se discute de forma agresiva"]', 'La tendencia de los individuos a esforzarse menos cuando trabajan en grupo que cuando lo hacen solos', 'Ocurre debido a la disipación de la responsabilidad individual en tareas grupales mal estructuradas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En resolución de conflictos, la estrategia de ''Compromiso'' (Compromising) implica:', 'opcion_multiple', '["Que una parte gane todo", "Ambas partes hacen concesiones mutuas para llegar a un acuerdo aceptable rápido (punto medio)", "Ignorar el problema hasta que pase", "Ceder incondicionalmente"]', 'Ambas partes hacen concesiones mutuas para llegar a un acuerdo aceptable rápido (punto medio)', 'Se usa cuando el tiempo apremia y ambas partes están dispuestas a sacrificar algo por un bien común.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La técnica del ''Anclaje'' en negociación se refiere a:', 'opcion_multiple', '["Fijar el barco de negociación en un tema", "El impacto de la primera oferta como punto de referencia mental para todo el debate posterior", "Firmar el contrato de inmediato", "Retirarse de la negociación"]', 'El impacto de la primera oferta como punto de referencia mental para todo el debate posterior', 'La primera cifra sugerida establece el rango psicológico inicial dentro del cual orbitará el acuerdo final.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La ''Motivación Extrínseca'' está impulsada por:', 'opcion_multiple', '["El disfrute de realizar la actividad por sí misma", "Factores externos como dinero, premios, reconocimientos públicos o para evitar castigos", "Valores personales profundos", "El crecimiento espiritual"]', 'Factores externos como dinero, premios, reconocimientos públicos o para evitar castigos', 'Depende de incentivos externos provistos por el entorno o la organización.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Cuál es la función principal de la retroalimentación o ''Feedback''?', 'opcion_multiple', '["Castigar el mal desempeño", "Proporcionar información objetiva sobre el comportamiento o desempeño pasado para guiar mejoras futuras", "Demostrar superioridad técnica", "Hacer evaluaciones anuales obligatorias"]', 'Proporcionar información objetiva sobre el comportamiento o desempeño pasado para guiar mejoras futuras', 'Su propósito es el desarrollo continuo y el alineamiento de expectativas entre los colaboradores.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el contexto laboral, el ''Síndrome del Impostor'' se manifiesta como:', 'opcion_multiple', '["Hacerse pasar por otra persona", "La creencia persistente de que tus éxitos se deben a la suerte y no a tus capacidades, sintiéndote un fraude", "Falsificar credenciales académicas", "Controlar de forma agresiva al equipo"]', 'La creencia persistente de que tus éxitos se deben a la suerte y no a tus capacidades, sintiéndote un fraude', 'Afecta el rendimiento de profesionales competentes debido al autosabotaje y la falta de autovaloración.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Para mitigar la ''Procrastinación'', una estrategia efectiva es:', 'opcion_multiple', '["Esperar el momento perfecto de inspiración", "Dividir tareas complejas en pasos pequeños y realizables (Acciones Atómicas)", "Trabajar bajo presión constante", "Hacer varias cosas al mismo tiempo"]', 'Dividir tareas complejas en pasos pequeños y realizables (Acciones Atómicas)', 'Reduce la fricción mental y la ansiedad inicial de iniciar un proyecto de gran envergadura.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Cuál es la principal desventaja del comportamiento ''Agresivo'' en la comunicación?', 'opcion_multiple', '["Consigue resultados rápidos", "Daña el clima laboral, rompe relaciones y bloquea la retroalimentación honesta", "Requiere hablar en voz muy alta", "No tiene desventajas"]', 'Daña el clima laboral, rompe relaciones y bloquea la retroalimentación honesta', 'Aunque impone metas inmediatas, destruye la confianza y seguridad psicológica del equipo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El autoconocimiento, componente de la Inteligencia Emocional, implica:', 'opcion_multiple', '["Controlar el comportamiento de los demás", "Reconocer las propias emociones y su impacto en nuestros pensamientos y conductas", "Estudiar la biografía de líderes", "Conocer las reglas de la empresa"]', 'Reconocer las propias emociones y su impacto en nuestros pensamientos y conductas', 'Es el punto de partida para aprender a autorregularnos de forma asertiva.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En dinámicas de comunicación, la ''Asertividad'' se sitúa en el punto de equilibrio entre:', 'opcion_multiple', '["La pasividad y la agresión", "La empatía y la simpatía", "El liderazgo y el control", "La oratoria y la escucha"]', 'La pasividad y la agresión', 'Permite defender tus derechos y expresar tus ideas respetando íntegramente los de los demás.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Un equipo en fase de ''Tormenta'' o conflicto (Storming) según Tuckman:', 'opcion_multiple', '["Es altamente productivo", "Experimenta tensiones, choques de personalidad y diferencias en metodologías de trabajo", "Ha alcanzado madurez plena", "Se disuelve por completo"]', 'Experimenta tensiones, choques de personalidad y diferencias en metodologías de trabajo', 'Es una transición normal donde el equipo debate liderazgos y normas antes de coordinarse.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El concepto de ''Negociación Integradora'' se orienta a:', 'opcion_multiple', '["Dividir el pastel en partes iguales fijas (Suma Cero)", "Crear valor y expandir el pastel buscando beneficios mutuos (Ganar-Ganar)", "Que la parte más fuerte se quede con todo", "Evitar negociar"]', 'Crear valor y expandir el pastel buscando beneficios mutuos (Ganar-Ganar)', 'Busca intereses comunes para plantear acuerdos creativos a largo plazo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La negociación ''Distributiva'' se define como:', 'opcion_multiple', '["Negociar con distribuidores", "Situaciones de Suma Cero, donde lo que una parte gana, la otra lo pierde necesariamente", "Una negociación de mutuo acuerdo", "Unión de equipos de trabajo"]', 'Situaciones de Suma Cero, donde lo que una parte gana, la otra lo pierde necesariamente', 'Generalmente ocurre en transacciones comerciales únicas basadas en precios o recursos fijos limitados.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Para mejorar la adaptabilidad ante cambios tecnológicos acelerados, el profesional debe cultivar:', 'opcion_multiple', '["Una mentalidad fija (Fixed Mindset)", "Una mentalidad de crecimiento (Growth Mindset) orientada al aprendizaje continuo", "Resignación constante", "Dependencia del líder"]', 'Una mentalidad de crecimiento (Growth Mindset) orientada al aprendizaje continuo', 'El Growth Mindset acoge el cambio y los errores como vías para la adquisición de competencias.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En resolución de problemas, el pensamiento divergente es útil para:', 'opcion_multiple', '["Encontrar una única respuesta correcta lógica", "Generar múltiples ideas creativas y alternativas sin juzgarlas inicialmente", "Tomar decisiones rápidas bajo presión", "Seguir un protocolo estricto"]', 'Generar múltiples ideas creativas y alternativas sin juzgarlas inicialmente', 'Fase inicial del brainstorming dedicada a la exploración amplia de ideas.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El pensamiento convergente se aplica para:', 'opcion_multiple', '["Tener muchas ideas creativas", "Filtrar, evaluar y seleccionar la mejor opción lógica entre varias alternativas", "Posponer decisiones", "Discutir en grupo"]', 'Filtrar, evaluar y seleccionar la mejor opción lógica entre varias alternativas', 'Fase de cierre de resolución de problemas, donde se selecciona e implementa la propuesta óptima.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La ''Técnica de los Seis Sombreros para Pensar'' de Edward de Bono ayuda a:', 'opcion_multiple', '["Tener sombreros de colores en las reuniones", "Analizar un problema desde seis perspectivas cognitivas y emocionales distintas en equipo", "Cambiar de puesto de trabajo de forma continua", "Ocultar las emociones durante el conflicto"]', 'Analizar un problema desde seis perspectivas cognitivas y emocionales distintas en equipo', 'Es un marco para pensamiento colaborativo que evita la confrontación de egos organizacionales.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo de De Bono, el ''Sombrero Negro'' representa:', 'opcion_multiple', '["El juicio lógico negativo, la precaución y los riesgos del proyecto", "La creatividad y las ideas absurdas", "El optimismo y los beneficios", "Las emociones y la intuición"]', 'El juicio lógico negativo, la precaución y los riesgos del proyecto', 'Analiza las posibles fallas o debilidades de la propuesta de forma racional.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El ''Sombrero Verde'' en el modelo de De Bono representa:', 'opcion_multiple', '["Los datos objetivos y fríos", "La creatividad, nuevas alternativas e ideas innovadoras", "Las emociones puras", "El control del proceso de pensamiento"]', 'La creatividad, nuevas alternativas e ideas innovadoras', 'Sombrero de la creación de propuestas alternativas sin limitaciones lógicas previas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La empatía en el liderazgo permite:', 'opcion_multiple', '["Perdonar todas las fallas sin exigir resultados", "Comprender la realidad interna del colaborador para guiarlo y apoyarlo de forma personalizada", "Hacerse amigos de todos", "Tomar decisiones basándose únicamente en el bienestar emocional"]', 'Comprender la realidad interna del colaborador para guiarlo y apoyarlo de forma personalizada', 'Mejora la comunicación e incrementa la confianza mutua y el compromiso laboral.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El micro-management (control excesivo del detalle) es perjudicial porque:', 'opcion_multiple', '["Requiere mucho tiempo del líder", "Destruye la autonomía, asfixia la iniciativa e incrementa la inseguridad del equipo", "Es ilegal en el país", "Solo se aplica en empresas grandes"]', 'Destruye la autonomía, asfixia la iniciativa e incrementa la inseguridad del equipo', 'Limita el crecimiento del equipo y desgasta inútilmente al supervisor.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Para recibir feedback destructivo con madurez, la mejor herramienta es:', 'opcion_multiple', '["La justificación constante de tus errores", "La indagación asertiva (preguntar por ejemplos concretos y objetivos para entender el punto real)", "Ponerse a la defensiva de inmediato", "Retirarse de la reunión en silencio"]', 'La indagación asertiva (preguntar por ejemplos concretos y objetivos para entender el punto real)', 'Ayuda a desactivar el ataque personal obligando al emisor a centrarse en datos prácticos y medibles.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En dinámicas de equipo, el ''Pensamiento de Grupo'' (Groupthink) es un peligro que consiste en:', 'opcion_multiple', '["Pensar de forma coordinada", "La tendencia a priorizar el consenso del grupo sobre el análisis crítico y objetivo de las ideas, callando disidencias", "No reunirse a tiempo", "Que solo el líder tiene la palabra"]', 'La tendencia a priorizar el consenso del grupo sobre el análisis crítico y objetivo de las ideas, callando disidencias', 'Frecuente en equipos muy homogéneos y cohesivos que evitan la controversia a costa de la calidad técnica.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Para evitar el ''Pensamiento de Grupo'', el líder puede:', 'opcion_multiple', '["Imponer su decisión inicial rápidamente", "Fomentar el debate abierto y designar a un miembro del equipo para que juegue el rol de ''Abogado del Diablo''", "No hacer reuniones de planeación", "Sancionar a quienes disientan"]', 'Fomentar el debate abierto y designar a un miembro del equipo para que juegue el rol de ''Abogado del Diablo''', 'Designar a alguien que busque fallas sistemáticamente legitima la crítica objetiva e impide consensos ciegos.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La ''Comunicación No Violenta'' (CNV) de Marshall Rosenberg propone cuatro componentes en orden:', 'opcion_multiple', '["Observación, Sentimiento, Necesidad, Petición", "Hecho, Reclamación, Juicio, Castigo", "Escuchar, Pensar, Decidir, Actuar", "Hablar, Evaluar, Cambiar, Cierre"]', 'Observación, Sentimiento, Necesidad, Petición', 'Es el marco de referencia asertivo para resolver conflictos interpersonales expresando necesidades sin ofender.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En la CNV de Rosenberg, el paso de ''Observación'' implica:', 'opcion_multiple', '["Juzgar el comportamiento ajeno", "Describir los hechos objetivos de forma clara sin mezclar evaluaciones o juicios de valor", "Expresar cómo te sientes", "Exigir una solución inmediata"]', 'Describir los hechos objetivos de forma clara sin mezclar evaluaciones o juicios de valor', 'Describir el hecho neutro evita la reacción defensiva inicial del interlocutor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La ''Automotivación'' consiste en:', 'opcion_multiple', '["Hacer lo que el jefe ordene", "La habilidad de dirigir el esfuerzo hacia metas personales o colectivas por convicción interna, superando dificultades", "Recibir bonos económicos", "Trabajar solo"]', 'La habilidad de dirigir el esfuerzo hacia metas personales o colectivas por convicción interna, superando dificultades', 'Es la disciplina interna que impulsa la acción sin requerir supervisión externa constante.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Un conflicto funcional en las organizaciones es aquel que:', 'opcion_multiple', '["Destruye la relación laboral", "Fomenta el debate saludable, cuestiona procesos obsoletos y cataliza la creatividad e innovación", "Se ignora por completo", "Termina en despido"]', 'Fomenta el debate saludable, cuestiona procesos obsoletos y cataliza la creatividad e innovación', 'La divergencia constructiva es indispensable para el crecimiento e innovación institucional.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El conflicto disfuncional en cambio:', 'opcion_multiple', '["Genera ideas creativas", "Desgasta la energía, daña las relaciones interpersonales y obstaculiza la productividad laboral", "No tiene impacto en la empresa", "Se soluciona con asertividad"]', 'Desgasta la energía, daña las relaciones interpersonales y obstaculiza la productividad laboral', 'Es destructivo y personal, por lo que el líder debe intervenir de inmediato para moderarlo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el contexto de negociación, la ''Zona de Posible Acuerdo'' (ZOPA) es:', 'opcion_multiple', '["La sala donde se firma el contrato", "El rango en el cual se cruzan las expectativas aceptables para ambas partes", "Un acuerdo internacional", "La cifra de dinero fija pactada"]', 'El rango en el cual se cruzan las expectativas aceptables para ambas partes', 'Espacio existente entre el límite mínimo del vendedor y el límite máximo de compra del comprador.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La negociación colaborativa busca crear relaciones a largo plazo. ¿Qué elemento es crucial para sostenerla?', 'opcion_multiple', '["La desconfianza mutua", "La transparencia, cumplimiento estricto de los pactos y honestidad comercial", "El secreto sobre los intereses reales", "Imponer penalizaciones severas"]', 'La transparencia, cumplimiento estricto de los pactos y honestidad comercial', 'La confianza mutua sustenta el flujo de información verídica y la viabilidad de futuros proyectos.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Una barrera física en la comunicación puede ser:', 'opcion_multiple', '["El prejuicio", "El ruido del entorno o fallas de conectividad técnica", "El idioma diferente", "El estrés personal"]', 'El ruido del entorno o fallas de conectividad técnica', 'Cualquier obstáculo del ambiente que afecte la transmisión física del mensaje.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Una barrera psicológica en la comunicación ocurre cuando:', 'opcion_multiple', '["No funciona el micrófono", "El emisor o receptor tiene sesgos, prejuicios o un estado emocional alterado que distorsiona el mensaje", "No se habla el mismo idioma", "Hay interferencia eléctrica"]', 'El emisor o receptor tiene sesgos, prejuicios o un estado emocional alterado que distorsiona el mensaje', 'Las emociones alteradas filtran y desvían la interpretación de las palabras emitidas.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La regla 80/20 (Principio de Pareto) en la gestión del tiempo sugiere que:', 'opcion_multiple', '["El 80% del tiempo se debe descansar y el 20% trabajar", "El 80% de tus logros proviene del 20% de tus esfuerzos enfocados en tareas clave", "Se debe contratar al 80% del personal", "El 80% de las tareas son fáciles"]', 'El 80% de tus logros proviene del 20% de tus esfuerzos enfocados en tareas clave', 'Ayuda a identificar y priorizar las actividades críticas que generan mayor impacto real.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En inteligencia emocional, el autoconocimiento te ayuda a identificar tus ''desencadenantes'' (triggers), que son:', 'opcion_multiple', '["Atajos de teclado", "Situaciones o comentarios específicos que activan en ti una reacción emocional desproporcionada o descontrolada", "Metas de rendimiento", "Tipos de liderazgo"]', 'Situaciones o comentarios específicos que activan en ti una reacción emocional desproporcionada o descontrolada', 'Reconocerlos de antemano te da el espacio racional para decidir tu respuesta de forma consciente.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, '¿Cuál es el beneficio de la ''Retroalimentación de pares'' (Peer feedback)?', 'opcion_multiple', '["Evitar la evaluación del jefe", "Obtener perspectivas operativas directas de colegas que trabajan en el mismo nivel técnico que tú", "Crear chismes", "Dividir responsabilidades"]', 'Obtener perspectivas operativas directas de colegas que trabajan en el mismo nivel técnico que tú', 'Aporta una óptica realista del trabajo diario que los supervisores directos no siempre perciben.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'El término ''Sinéctica'' se refiere a:', 'opcion_multiple', '["El estudio del movimiento", "Un método de estimulación de la creatividad mediante la unión de elementos aparentemente irrelevantes", "Una técnica de oratoria", "El control del estrés"]', 'Un método de estimulación de la creatividad mediante la unión de elementos aparentemente irrelevantes', 'Usa analogías y comparaciones para forzar conexiones novedosas y originales frente a un reto.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En dinámicas de equipo, un ''Líder Facilitador'':', 'opcion_multiple', '["Toma todas las decisiones de forma autocrática", "Apoya al equipo eliminando barreras, guiando el proceso y empoderándolos para decidir", "Da libertad absoluta sin acompañar", "Solo inspecciona el horario"]', 'Apoya al equipo eliminando barreras, guiando el proceso y empoderándolos para decidir', 'Combina el apoyo y la autonomía para potenciar la autogestión y compromiso.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La adaptabilidad se manifiesta en el trabajo cuando un profesional:', 'opcion_multiple', '["Se resiste a usar nuevos programas informáticos", "Ajusta rápidamente sus planes y formas de actuar frente a imprevistos o nuevas prioridades", "Exige un contrato rígido", "Trabaja de forma aislada"]', 'Ajusta rápidamente sus planes y formas de actuar frente a imprevistos o nuevas prioridades', 'Es la capacidad de responder asertivamente al cambio continuo sin frustrarse.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo DISC de comportamiento, la ''D'' representa:', 'opcion_multiple', '["Decisión / Dominancia (orientación a resultados, control y retos rápidos)", "Detalle / Diplomacia", "Delegación", "Desarrollo"]', 'Decisión / Dominancia (orientación a resultados, control y retos rápidos)', 'El estilo Dominante es directo, enfocado en metas inmediatas y competitivo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo DISC, la ''I'' representa:', 'opcion_multiple', '["Inteligencia", "Influencia (personas optimistas, persuasivas, comunicativas y orientadas al equipo)", "Instrucción", "Iniciativa pasiva"]', 'Influencia (personas optimistas, persuasivas, comunicativas y orientadas al equipo)', 'El estilo Influyente conecta socialmente con facilidad y motiva al grupo mediante el entusiasmo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo DISC, la ''S'' representa:', 'opcion_multiple', '["Seguridad / Estabilidad (personas colaboradoras, pacientes, persistentes y leales)", "Sinceridad", "Soporte técnico", "Silencio"]', 'Seguridad / Estabilidad (personas colaboradoras, pacientes, persistentes y leales)', 'El estilo Estable (Steadiness) valora la rutina predecible y la armonía relacional.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'En el modelo DISC, la ''C'' representa:', 'opcion_multiple', '["Control asertivo", "Cumplimiento / Concienciación (personas analíticas, precisas, atentas a las normas y la calidad)", "Creatividad extrema", "Cohesión social"]', 'Cumplimiento / Concienciación (personas analíticas, precisas, atentas a las normas y la calidad)', 'El estilo Concienzudo prioriza la lógica, la exactitud de los datos y el seguimiento de procesos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Una crítica constructiva debe formularse utilizando enunciados en primera persona (ej. ''Yo noté...'') para:', 'opcion_multiple', '["Imponer tu criterio", "Asumir tu percepción de forma asertiva evitando sonar acusatorio directivo (''Tú hiciste...'')", "Hacerse responsable del error", "Ahorrar tiempo"]', 'Asumir tu percepción de forma asertiva evitando sonar acusatorio directivo (''Tú hiciste...'')', 'Enunciar desde tu óptica reduce la hostilidad del receptor y abre espacio al diálogo objetivo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La técnica asertiva del ''Disco rayado'' consiste en:', 'opcion_multiple', '["Repetir tu postura con calma, firmeza y con las mismas palabras ante la insistencia ajena, sin alterarte", "Interrumpir constantemente", "Hablar de forma incomprensible", "Ceder después de tres intentos"]', 'Repetir tu postura con calma, firmeza y con las mismas palabras ante la insistencia ajena, sin alterarte', 'Evita manipulaciones o desvíos del tema central sin caer en agresiones verbales.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La técnica del ''Banco de niebla'' en asertividad te ayuda a:', 'opcion_multiple', '["Ignorar los hechos por completo", "Dar la razón en parte a la crítica ajena de forma neutra sin ceder en tu postura o decisión de fondo", "Crear confusión", "Pedir disculpas exageradas"]', 'Dar la razón en parte a la crítica ajena de forma neutra sin ceder en tu postura o decisión de fondo', 'Desarma la agresión del otro al no confrontar su enojo de forma reactiva.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En la gestión del alcance, ¿cuál es la función del ''Diccionario de la EDT''?', 'opcion_multiple', '["Traducir términos técnicos", "Detallar de forma exhaustiva el trabajo, criterios de aceptación y entregables de cada paquete de trabajo de la EDT", "Listar los nombres del equipo", "Controlar los costos"]', 'Detallar de forma exhaustiva el trabajo, criterios de aceptación y entregables de cada paquete de trabajo de la EDT', 'Evita desviaciones de alcance al definir con precisión los límites de cada paquete de trabajo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, '¿Qué describe la holgura libre (Free Float) de una tarea?', 'opcion_multiple', '["El tiempo de retraso sin alterar la fecha de finalización del proyecto completo", "El tiempo que se puede retrasar la tarea sin afectar el inicio temprano de sus sucesoras inmediatas", "La duración óptima de la tarea", "La holgura de la ruta crítica"]', 'El tiempo que se puede retrasar la tarea sin afectar el inicio temprano de sus sucesoras inmediatas', 'Difiere de la holgura total en que solo afecta a la tarea sucesora y no al hito de cierre del proyecto.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En el CPM (Critical Path Method), si una tarea pertenece a la ruta crítica, ¿cuál es su holgura total?', 'opcion_multiple', '["Cero", "Máxima", "Mínimo una semana", "Depende del presupuesto"]', 'Cero', 'Las tareas críticas no tienen flexibilidad de tiempo; cualquier retraso en ellas desplaza la entrega final.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La técnica de compresión del cronograma llamada ''Crashing'' (Intensificación) consiste en:', 'opcion_multiple', '["Ejecutar actividades en paralelo", "Agregar recursos adicionales a las tareas críticas para reducir su duración al menor costo posible", "Recortar el alcance", "Aumentar el plazo"]', 'Agregar recursos adicionales a las tareas críticas para reducir su duración al menor costo posible', 'Reduce el tiempo de ejecución a costa de incrementar los costos directos del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La técnica de compresión del cronograma llamada ''Fast Tracking'' (Ejecución rápida) implica:', 'opcion_multiple', '["Comprar computadoras rápidas", "Realizar tareas que normalmente se harían en secuencia de forma paralela durante un tramo", "Eliminar hitos", "Doblar turnos de trabajo"]', 'Realizar tareas que normalmente se harían en secuencia de forma paralela durante un tramo', 'Aumenta la probabilidad de reprocesos y eleva el riesgo del cronograma sin costo adicional inmediato.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En estimación de costos, la ''Estimación Análoga'':', 'opcion_multiple', '["Usa fórmulas estadísticas complejas", "Usa la información histórica de proyectos similares anteriores como base para estimar el costo actual (rápido pero menos preciso)", "Requiere detallar cada tarea al máximo", "Es un cálculo matemático paramétrico"]', 'Usa la información histórica de proyectos similares anteriores como base para estimar el costo actual (rápido pero menos preciso)', 'Es una estimación top-down basada en la experiencia histórica acumulada.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La ''Estimación Paramétrica'' de costos se caracteriza por:', 'opcion_multiple', '["Preguntar a expertos", "Usar una relación estadística basada en datos históricos para calcular costos (ej. costo por metro cuadrado)", "Hacer una suma simple", "Ser la más imprecisa"]', 'Usar una relación estadística basada en datos históricos para calcular costos (ej. costo por metro cuadrado)', 'Usa variables métricas para escalar estimaciones matemáticamente (ej. líneas de código, metros construidos).', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En EVM (Earned Value Management), la fórmula para calcular la Variación de Costo (CV) es:', 'opcion_multiple', '["CV = EV - AC", "CV = EV - PV", "CV = AC - PV", "CV = EV / AC"]', 'CV = EV - AC', 'CV mide la diferencia entre el valor del trabajo realmente completado (EV) y los costos reales erogados (AC).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'Si el Índice de Desempeño del Costo (CPI) de un proyecto es 0.85, esto significa:', 'opcion_multiple', '["El proyecto va adelantado", "El proyecto está gastando más de lo planificado (por cada peso invertido, se obtienen 0.85 de valor)", "El proyecto va a tiempo", "El presupuesto es correcto"]', 'El proyecto está gastando más de lo planificado (por cada peso invertido, se obtienen 0.85 de valor)', 'Un CPI < 1.0 indica sobrecosto. Un CPI > 1.0 indica ahorros presupuestales.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En EVM, la fórmula para calcular la Variación de Cronograma (SV) es:', 'opcion_multiple', '["SV = EV - PV", "SV = EV - AC", "SV = PV - AC", "SV = EV / PV"]', 'SV = EV - PV', 'SV compara el valor ganado (EV) con el valor planificado al día de hoy (PV) en términos monetarios.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'Si el Índice de Desempeño del Cronograma (SPI) es 1.2, esto significa:', 'opcion_multiple', '["El proyecto va retrasado", "El proyecto va adelantado respecto al cronograma (20% más eficiente)", "El proyecto va a tiempo", "El proyecto gasta de más"]', 'El proyecto va adelantado respecto al cronograma (20% más eficiente)', 'Un SPI > 1.0 representa eficiencia en el avance del plan de trabajo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En la gestión de riesgos, una respuesta de ''Transferir'' el riesgo implica:', 'opcion_multiple', '["Ignorar el riesgo", "Pasar la responsabilidad del impacto y propiedad del riesgo a un tercero (ej. comprar un seguro)", "Cambiar el diseño para anularlo", "Mitigar la probabilidad"]', 'Pasar la responsabilidad del impacto y propiedad del riesgo a un tercero (ej. comprar un seguro)', 'La transferencia traslada el riesgo financiero o legal a otra entidad bajo contrato.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La diferencia entre la ''Reserva de Contingencia'' y la ''Reserva de Gestión'' en costos es:', 'opcion_multiple', '["No hay diferencia", "Contingencia es para riesgos identificados (conocidos-desconocidos); Gestión es para imprevistos no identificados (desconocidos-desconocidos)", "Contingencia la aprueba el cliente y Gestión el director", "Contingencia es solo para tiempo"]', 'Contingencia es para riesgos identificados (conocidos-desconocidos); Gestión es para imprevistos no identificados (desconocidos-desconocidos)', 'La reserva de contingencia forma parte de la línea base de costos; la reserva de gestión no, requiriendo control de cambios formal.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Scrum, ¿quién es el único responsable de gestionar y priorizar el Product Backlog?', 'opcion_multiple', '["El Scrum Master", "El Product Owner", "El cliente final", "El equipo de desarrollo"]', 'El Product Owner', 'El Product Owner maximiza el valor del producto y representa la voz del cliente ante el equipo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El propósito del evento ''Sprint Retrospective'' en Scrum es:', 'opcion_multiple', '["Demostrar el incremento de software al cliente", "Inspeccionar cómo le fue al equipo en procesos, relaciones y herramientas para acordar mejoras continuas", "Planear las tareas del próximo Sprint", "Dar reporte diario al Product Owner"]', 'Inspeccionar cómo le fue al equipo en procesos, relaciones y herramientas para acordar mejoras continuas', 'Evento enfocado en la mejora continua y evolución interna del propio equipo Scrum.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Kanban, el ''Lead Time'' (Tiempo de Entrega) mide:', 'opcion_multiple', '["La velocidad de desarrollo", "El tiempo total transcurrido desde que surge el requisito del cliente hasta que se entrega formalmente", "El tiempo que la tarea pasa en desarrollo", "El tiempo de pruebas"]', 'El tiempo total transcurrido desde que surge el requisito del cliente hasta que se entrega formalmente', 'Abarca todo el flujo de valor, incluyendo colas de espera iniciales en el backlog.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Kanban, el ''Cycle Time'' (Tiempo de Ciclo) mide:', 'opcion_multiple', '["El tiempo de reuniones", "El tiempo transcurrido desde que se inicia activamente el desarrollo de la tarea hasta que se completa", "El lead time completo", "El avance del cronograma"]', 'El tiempo transcurrido desde que se inicia activamente el desarrollo de la tarea hasta que se completa', 'Mide el rendimiento operativo directo del equipo de trabajo sin tiempos de espera comerciales previos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En la Matriz de Poder/Interés para stakeholders, a un actor con ''Alto Poder'' y ''Bajo Interés'' se le debe:', 'opcion_multiple', '["Monitorear de cerca", "Mantener Satisfecho", "Gestionar de cerca", "Mantener Informado"]', 'Mantener Satisfecho', 'Por tener alto poder político/económico pero bajo interés actual, se busca evitar conflictos satisfaciendo sus necesidades.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'A un stakeholder con ''Alto Poder'' y ''Alto Interés'' se le debe:', 'opcion_multiple', '["Mantener Satisfecho", "Gestionar Atentamente / Involucrar activamente", "Mantener Informado", "Monitorear mínimamente"]', 'Gestionar Atentamente / Involucrar activamente', 'Son los aliados o detractores críticos del proyecto que requieren el mayor nivel de coordinación y atención.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El Acta de Constitución del Proyecto (Project Charter) es aprobada formalmente por:', 'opcion_multiple', '["El Scrum Master", "El Patrocinador del Proyecto (Sponsor) o cliente iniciador", "El líder de desarrollo", "El Project Manager"]', 'El Patrocinador del Proyecto (Sponsor) o cliente iniciador', 'El Sponsor autoriza el proyecto y dota al Project Manager de la autoridad para asignar recursos organizacionales.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En una Matriz RACI, la letra ''A'' (Accountable) representa a:', 'opcion_multiple', '["Quien ejecuta el trabajo técnico", "La persona que asume la responsabilidad final de la tarea y toma decisiones (solo una persona por tarea)", "Quien da asesoramiento técnico", "El cliente final"]', 'La persona que asume la responsabilidad final de la tarea y toma decisiones (solo una persona por tarea)', 'El Accountable rinde cuentas por el resultado y delega la ejecución en los Responsible (R).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, '¿Cuántas personas pueden ser ''Accountable'' (A) por cada actividad en la matriz RACI?', 'opcion_multiple', '["Mínimo dos", "Exactamente una sola persona", "Cualquier número", "No es necesario definirlo"]', 'Exactamente una sola persona', 'Tener más de un Accountable diluye la rendición de cuentas, generando inacción u omisión en decisiones.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El diagrama ''Burn-down'' muestra:', 'opcion_multiple', '["La velocidad de internet", "El trabajo restante del proyecto o sprint acumulado contra el paso del tiempo", "Los costos reales de los materiales", "El organigrama del equipo"]', 'El trabajo restante del proyecto o sprint acumulado contra el paso del tiempo', 'Visualiza el progreso restante; una línea en declive hacia cero conforme avanzan los días.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El diagrama ''Burn-up'' muestra:', 'opcion_multiple', '["Solo los bugs", "El trabajo total completado de forma acumulativa y el alcance del proyecto contra el tiempo", "Las horas extra", "El presupuesto gastado"]', 'El trabajo total completado de forma acumulativa y el alcance del proyecto contra el tiempo', 'Permite visualizar cambios de alcance en el proyecto reflejando el incremento de la meta total.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, '¿Qué describe la holgura total (Total Float) de una tarea?', 'opcion_multiple', '["El retraso posible sin alterar la fecha final de entrega comprometida del proyecto completo", "El avance de sus tareas sucesoras", "El costo total", "La duración total"]', 'El retraso posible sin alterar la fecha final de entrega comprometida del proyecto completo', 'Margen de maniobra temporal de un camino en la red sin demorar la fecha final establecida.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En estimación de costos, la estimación ''Bottom-Up'' (Ascendente) es conocida por ser:', 'opcion_multiple', '["La más rápida e imprecisa", "La más detallada, lenta y precisa (calcula costo de cada tarea menor y las consolida hacia arriba)", "Un promedio de experto", "Una fórmula paramétrica"]', 'La más detallada, lenta y precisa (calcula costo de cada tarea menor y las consolida hacia arriba)', 'Requiere desglosar la EDT al nivel de paquetes de trabajo concretos para costearlos por separado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En el contexto de la gestión de riesgos, el análisis cuantitativo de riesgos busca:', 'opcion_multiple', '["Listar los riesgos de forma narrativa", "Asignar valores numéricos de probabilidad e impacto económico o de tiempo al proyecto completo (ej. simulaciones Monte Carlo)", "Evaluar opiniones personales", "No tiene utilidad"]', 'Asignar valores numéricos de probabilidad e impacto económico o de tiempo al proyecto completo (ej. simulaciones Monte Carlo)', 'Usa modelos matemáticos estructurados para estimar rangos probabilísticos de cierre (costos/plazos).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Scrum, la duración de una sesión de Sprint Planning está típicamente limitada a:', 'opcion_multiple', '["15 minutos diarios", "Máximo 8 horas para un Sprint de un mes (proporcional para sprints cortos)", "2 horas semanales fijas", "No tiene límite de tiempo"]', 'Máximo 8 horas para un Sprint de un mes (proporcional para sprints cortos)', 'Es un evento time-boxed que se ajusta a la duración propuesta de la iteración.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En un diagrama de Gantt, las líneas o flechas que conectan las barras horizontales representan:', 'opcion_multiple', '["El nombre de las personas", "Las dependencias o relaciones lógicas entre tareas (ej. Fin a Inicio)", "Los costos", "El porcentaje de avance"]', 'Las dependencias o relaciones lógicas entre tareas (ej. Fin a Inicio)', 'Muestran la secuencia obligada de ejecución de actividades del cronograma.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La técnica Delphi en estimación se caracteriza por:', 'opcion_multiple', '["Votación directa a mano alzada", "Consultas a expertos de forma anónima en rondas iterativas para llegar a un consenso sin sesgos grupales", "Cálculo matemático paramétrico", "Estimaciones análogas"]', 'Consultas a expertos de forma anónima en rondas iterativas para llegar a un consenso sin sesgos grupales', 'El anonimato de Delphi evita que líderes influyentes dominen la opinión en la estimación grupal.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En dirección de proyectos, un ''Hito'' (Milestone) tiene por definición una duración de:', 'opcion_multiple', '["1 día", "Cero (es un evento o logro significativo con duración nula)", "Una semana", "Variable según alcance"]', 'Cero (es un evento o logro significativo con duración nula)', 'Los hitos marcan momentos de control clave (ej. firma de contrato, entrega de prototipo) sin consumir tiempo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La ''Corrupción del Alcance'' (Scope Creep) se define como:', 'opcion_multiple', '["Tener fallas de presupuesto", "La expansión descontrolada del alcance de un proyecto sin ajustes formales de presupuesto, tiempo o aprobación del sponsor", "Que los desarrolladores cometan errores", "El fin del proyecto antes de tiempo"]', 'La expansión descontrolada del alcance de un proyecto sin ajustes formales de presupuesto, tiempo o aprobación del sponsor', 'Es un factor crítico de fracaso que satura el cronograma por aceptar solicitudes informales.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El término ''Línea Base'' (Baseline) en gestión de proyectos:', 'opcion_multiple', '["Es la base de datos", "Es la versión aprobada del plan de alcance, cronograma y costos que se usa como referencia para medir y controlar variaciones", "El organigrama", "Los contratos"]', 'Es la versión aprobada del plan de alcance, cronograma y costos que se usa como referencia para medir y controlar variaciones', 'Permite contrastar el desempeño real contra lo planificado inicialmente ante auditorías.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En la gestión de la calidad, el Aseguramiento de Calidad (QA) se enfoca en:', 'opcion_multiple', '["Inspeccionar el producto final para buscar fallas", "Mejorar los procesos organizacionales para garantizar que se cumplan los estándares de calidad de forma consistente (prevención)", "Hacer pruebas de software manuales", "Satisfacer al sponsor"]', 'Mejorar los procesos organizacionales para garantizar que se cumplan los estándares de calidad de forma consistente (prevención)', 'QA previene defectos optimizando metodologías; QC detecta fallas inspeccionando entregables.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El Control de Calidad (QC) por su parte se enfoca en:', 'opcion_multiple', '["Rediseñar procesos", "Inspeccionar y verificar que los entregables específicos cumplan con los criterios de aceptación técnicos establecidos", "Planificar costos", "Capacitar al personal"]', 'Inspeccionar y verificar que los entregables específicos cumplan con los criterios de aceptación técnicos establecidos', 'Orientado a medir y validar el producto final antes de su entrega al cliente.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En dirección de proyectos, una ''Restricción'' es:', 'opcion_multiple', '["Un riesgo potencial", "Un factor limitante o condición obligada que afecta la ejecución del proyecto (ej. presupuesto fijo, plazo legal)", "Una suposición que consideramos verdadera", "Un cambio de alcance"]', 'Un factor limitante o condición obligada que afecta la ejecución del proyecto (ej. presupuesto fijo, plazo legal)', 'Las restricciones delimitan el marco operacional y deben cumplirse estrictamente.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En el análisis cualitativo de riesgos, se priorizan los riesgos basándose en dos factores primarios:', 'opcion_multiple', '["Costo y Tiempo", "Probabilidad de ocurrencia e Impacto en los objetivos", "Cantidad y Severidad", "Frecuencia e Historial"]', 'Probabilidad de ocurrencia e Impacto en los objetivos', 'La ponderación de Probabilidad x Impacto ubica los riesgos en una matriz de prioridad para asignar planes de respuesta.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, '¿Qué describe la ''Estructura de Desglose de Recursos'' (RBS)?', 'opcion_multiple', '["El organigrama de la empresa", "Descomposición jerárquica de los recursos del proyecto clasificados por tipo y categoría", "Los perfiles de puesto", "La lista de salarios"]', 'Descomposición jerárquica de los recursos del proyecto clasificados por tipo y categoría', 'Ayuda a inventariar y rastrear la provisión de personal, equipo y materiales del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En PMBOK, la ''Gestión de la Integración'' incluye procesos destinados a:', 'opcion_multiple', '["Contratar personal nuevo", "Identificar, definir, combinar, unificar y coordinar los diversos procesos y actividades de dirección de proyectos", "Integrar sistemas informáticos", "Alinear la base de datos"]', 'Identificar, definir, combinar, unificar y coordinar los diversos procesos y actividades de dirección de proyectos', 'Es la responsabilidad central del Project Manager para mantener cohesión general en el proyecto.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La diferencia entre ''Validar el Alcance'' y ''Controlar el Alcance'' en PMBOK es:', 'opcion_multiple', '["No tienen diferencia", "Validar es conseguir la aceptación formal firmada del cliente de los entregables; Controlar es vigilar variaciones del plan de trabajo", "Validar es probar el software y Controlar es vigilar el presupuesto", "Validar ocurre al inicio y Controlar al cierre"]', 'Validar es conseguir la aceptación formal firmada del cliente de los entregables; Controlar es vigilar variaciones del plan de trabajo', 'Validar el alcance se enfoca en la conformidad formal del cliente para autorizar el cierre o facturación.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El término ''Lecciones Aprendidas'' debe ser documentado y compartido:', 'opcion_multiple', '["Únicamente al final del proyecto en el cierre", "A lo largo de todo el ciclo de vida del proyecto, de manera continua e incremental", "Solo si el proyecto fracasó", "Para sancionar a los desarrolladores"]', 'A lo largo de todo el ciclo de vida del proyecto, de manera continua e incremental', 'Su registro continuo nutre la base de conocimiento organizacional para evitar errores en fases subsecuentes.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, '¿Cuál es la función del ''Comité de Control de Cambios'' (CCB)?', 'opcion_multiple', '["Organizar las reuniones semanales", "Evaluar, aprobar o rechazar las solicitudes de cambio a las líneas base del proyecto bajo procedimiento formal", "Diseñar los entregables", "Inspeccionar la calidad de la planta"]', 'Evaluar, aprobar o rechazar las solicitudes de cambio a las líneas base del proyecto bajo procedimiento formal', 'El CCB protege la integridad de las líneas base asegurando un análisis de impacto multidimensional previo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En la estimación de tres valores (PERT), la fórmula estándar para calcular la duración esperada (Te) es:', 'opcion_multiple', '["Te = (P + 4M + O) / 6", "Te = (P + M + O) / 3", "Te = (P + O) / 2", "Te = (4P + M + O) / 6"]', 'Te = (P + 4M + O) / 6', 'La distribución beta otorga un peso mayor al valor más probable (M) respecto al pesimista (P) y optimista (O).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Scrum, ¿qué es la ''Definición de Terminado'' (Definition of Done - DoD)?', 'opcion_multiple', '["La lista de tareas pendientes", "Un entendimiento común y criterio objetivo de calidad que debe cumplir todo incremento para considerarse entregable", "La fecha de cierre de la empresa", "La orden del Product Owner"]', 'Un entendimiento común y criterio objetivo de calidad que debe cumplir todo incremento para considerarse entregable', 'Asegura la transparencia impidiendo que items con bugs sean catalogados como terminados.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, '¿Qué describe el ''Sprint Backlog'' en Scrum?', 'opcion_multiple', '["Lista de requisitos del cliente a largo plazo", "Subconjunto del Product Backlog seleccionado para el Sprint actual junto con el plan para entregarlo", "Los reportes de calidad pasados", "El histórico de velocidad del equipo"]', 'Subconjunto del Product Backlog seleccionado para el Sprint actual junto con el plan para entregarlo', 'Es propiedad exclusiva del equipo de desarrollo, quienes lo gestionan y actualizan durante el Sprint.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Scrum, si el equipo detecta que no podrá completar todos los elementos comprometidos a mitad del Sprint, ¿qué debe hacer?', 'opcion_multiple', '["Trabajar horas extra obligatorias sin avisar", "Colaborar con el Product Owner de inmediato para negociar y reajustar el alcance del Sprint Backlog sin comprometer la calidad", "Cancelar el Sprint de inmediato", "No entregar nada"]', 'Colaborar con el Product Owner de inmediato para negociar y reajustar el alcance del Sprint Backlog sin comprometer la calidad', 'La transparencia y colaboración permiten adaptar el alcance antes de la revisión final sin generar sorpresas al cliente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El manifiesto ágil prioriza: ''Software funcionando sobre...''', 'opcion_multiple', '["Personas e interacciones", "Documentación exhaustiva", "Negociación contractual", "Seguimiento de un plan"]', 'Documentación exhaustiva', 'Valora la documentación pero da mayor valor al software útil entregado de forma real.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El manifiesto ágil prioriza: ''Colaboración con el cliente sobre...''', 'opcion_multiple', '["Procesos y herramientas", "Negociación contractual", "Documentación técnica", "Cronogramas de Gantt"]', 'Negociación contractual', 'Busca entablar relaciones de confianza y cocreación en lugar de discusiones de cláusulas rígidas.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El manifiesto ágil prioriza: ''Respuesta ante el cambio sobre...''', 'opcion_multiple', '["Seguimiento de un plan", "Procesos fijos", "Herramientas ágiles", "Contratos comerciales"]', 'Seguimiento de un plan', 'La agilidad reside en la capacidad de responder al cambio de mercado con flexibilidad en la planeación.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Scrum, ¿quién tiene la facultad de cancelar un Sprint en progreso si la meta pierde sentido?', 'opcion_multiple', '["El Scrum Master", "Únicamente el Product Owner", "El equipo de desarrollo", "El Sponsor de forma directa"]', 'Únicamente el Product Owner', 'El Product Owner asume la viabilidad del negocio, por lo que posee la autoridad exclusiva para tomar esta decisión.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La diferencia entre ''Tiempo de ciclo'' e ''Índice de rendimiento'' (Throughput) en Kanban es:', 'opcion_multiple', '["No tienen relación", "El tiempo de ciclo mide la duración por tarea individual; el throughput mide la cantidad de tareas completadas por unidad de tiempo", "Throughput es el costo del proceso", "El tiempo de ciclo lo mide el Product Owner y throughput el equipo"]', 'El tiempo de ciclo mide la duración por tarea individual; el throughput mide la cantidad de tareas completadas por unidad de tiempo', 'El Throughput mide la tasa de salida o productividad global del sistema (ej. 5 tareas finalizadas por semana).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El ''Backlog Grooming'' (o Refinamiento del Backlog) en metodologías ágiles consiste en:', 'opcion_multiple', '["Cerrar el proyecto", "Analizar, estimar, detallar y priorizar historias de usuario con anticipación al Sprint Planning", "Hacer pruebas de integración", "Entregar el software al cliente"]', 'Analizar, estimar, detallar y priorizar historias de usuario con anticipación al Sprint Planning', 'Prepara y mantiene lista la bolsa de requisitos para acelerar las siguientes planeaciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En Scrum, ¿cuál es el rol principal del Scrum Master durante el Daily Scrum?', 'opcion_multiple', '["Dirigir la reunión y tomar asistencia", "Asegurar que el evento ocurra, se mantenga dentro del límite de 15 minutos y enseñar al equipo a autogestionarse", "Tomar decisiones técnicas", "Dar reportes al Product Owner"]', 'Asegurar que el evento ocurra, se mantenga dentro del límite de 15 minutos y enseñar al equipo a autogestionarse', 'El Scrum Master actúa como facilitador y coach, no como jefe de proyecto dictatorial.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'Un proyecto se define de forma estándar como:', 'opcion_multiple', '["Una operación repetitiva sin fin", "Un esfuerzo temporal que se lleva a cabo para crear un producto, servicio o resultado único", "Cualquier actividad grupal", "Un plan presupuestal anual"]', 'Un esfuerzo temporal que se lleva a cabo para crear un producto, servicio o resultado único', 'Sus dos características distintivas son la temporalidad (tiene inicio y fin definidos) y la singularidad de su entregable.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En la gestión de interesados, el registro de interesados (Stakeholder Register) se crea inicialmente en la fase de:', 'opcion_multiple', '["Planificación", "Inicio (identificación y mapeo inicial)", "Ejecución", "Cierre"]', 'Inicio (identificación y mapeo inicial)', 'Es un documento vivo que surge desde el acta de constitución para guiar la planificación posterior.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'La Matriz de Trazabilidad de Requisitos sirve para:', 'opcion_multiple', '["Calcular costos de materiales", "Vincular los requisitos del proyecto desde su origen hasta los entregables que los satisfacen (rastreabilidad)", "Dibujar el cronograma de Gantt", "Registrar las firmas de los desarrolladores"]', 'Vincular los requisitos del proyecto desde su origen hasta los entregables que los satisfacen (rastreabilidad)', 'Asegura que cada requisito aprobado sea probado y entregado formalmente al cierre.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'En la gestión del tiempo, el método del ''Camino Crítico'' calcula:', 'opcion_multiple', '["El costo del proyecto", "La duración mínima total del proyecto y las fechas de inicio y fin tempranas y tardías para todas las actividades", "Los riesgos del cronograma", "La velocidad del equipo"]', 'La duración mínima total del proyecto y las fechas de inicio y fin tempranas y tardías para todas las actividades', 'Determina la secuencia lógica de tareas obligatorias que marcan la pauta del proyecto completo.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El término ''Holgura'' (Float) indica general y matemáticamente:', 'opcion_multiple', '["El costo extra del proyecto", "La flexibilidad de tiempo de una actividad para retrasarse sin impactar las fechas límite (Tardío - Temprano)", "El tamaño de la reserva de gestión", "Las horas extra consumidas"]', 'La flexibilidad de tiempo de una actividad para retrasarse sin impactar las fechas límite (Tardío - Temprano)', 'La diferencia entre los tiempos límite de inicio/fin tardíos y tempranos de una tarea.', 'basico');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'El Índice de Desempeño del Trabajo por Completar (TCPI) en EVM calcula:', 'opcion_multiple', '["La velocidad de desarrollo de código", "El rendimiento del costo que el equipo debe alcanzar para cumplir con el presupuesto restante (BAC)", "El tiempo que le queda al proyecto", "La rentabilidad financiera de la empresa"]', 'El rendimiento del costo que el equipo debe alcanzar para cumplir con el presupuesto restante (BAC)', 'TCPI indica qué tan eficientes debemos ser a partir de hoy para no pasarnos del presupuesto original.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (8, 'Si la Variación de Cronograma (SV) es igual a cero, esto significa:', 'opcion_multiple', '["El proyecto está detenido", "El proyecto está exactamente al día respecto al plan de cronograma presupuestado", "El proyecto no tiene costos reales", "El proyecto se canceló"]', 'El proyecto está exactamente al día respecto al plan de cronograma presupuestado', 'Indica alineación exacta de los hitos calendarizados contra el avance real de las actividades.', 'basico');
